import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Garden extends JPanel {
    int x=300,y=220; long started=System.currentTimeMillis(); int moves=0;
    public Garden(){setFocusable(true);setBackground(new Color(23,41,39));addKeyListener(new KeyAdapter(){public void keyPressed(KeyEvent e){switch(e.getKeyCode()){case KeyEvent.VK_LEFT: x-=12;break;case KeyEvent.VK_RIGHT:x+=12;break;case KeyEvent.VK_UP:y-=12;break;case KeyEvent.VK_DOWN:y+=12;break;case KeyEvent.VK_SPACE:moves+=10;break;default:break;}x=Math.max(30,Math.min(590,x));y=Math.max(125,Math.min(350,y));moves++;repaint();}});new Timer(1000,e->repaint()).start();}
    public void paintComponent(Graphics g){super.paintComponent(g);g.setColor(new Color(179,237,117));g.setFont(new Font("SansSerif",Font.BOLD,24));g.drawString("JAVA GARDEN",30,46);g.setColor(new Color(151,178,166));g.setFont(new Font("SansSerif",Font.PLAIN,13));g.drawString("ThueTab / isolated Java runtime / your private world",30,73);for(int i=0;i<20;i++){g.setColor(new Color(35,64,47));g.fillRect(i*32,120+(i%3)*24,32,264);}g.setColor(new Color(103,143,68));g.fillRect(0,374,640,42);for(int i=0;i<8;i++){g.setColor(new Color(65,102,49));g.fillRect(i*90+20,280,13,95);g.setColor(new Color(105,159,74));g.fillRect(i*90+2,248,48,45);}g.setColor(new Color(244,205,107));g.fillRect(x,y,22,27);g.setColor(new Color(236,221,173));g.fillRect(x+3,y-12,16,15);g.setColor(new Color(21,31,30));g.fillRect(x+13,y-6,3,3);g.setColor(new Color(210,228,201));g.setFont(new Font("Monospaced",Font.PLAIN,13));g.drawString("Uptime: "+(System.currentTimeMillis()-started)/1000+"s  |  Actions: "+moves,25,440);g.drawString("Arrow keys: move    Space: collect",25,462);}
    public static void main(String[] args){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Java Garden");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setUndecorated(true);Garden p=new Garden();f.add(p);f.setSize(640,480);f.setVisible(true);p.requestFocusInWindow();});}
}
